export class CredentialCache{constructor(){this.entries=new Map}set(e,t){const r=this.entries.get(e);if(r)return r.ownerId=t.ownerId,r.orgId=t.orgId,r.writeToken=t.writeToken,r.agentName=t.agentName,void(r.environment=t.environment);this.entries.set(e,{...t,streamIds:new Set})}get(e){return this.entries.get(e)}addStream(e,t){const r=this.entries.get(e);r&&r.streamIds.add(t)}remove(e){this.entries.delete(e)}has(e){return this.entries.has(e)}taskIds(){return[...this.entries.keys()]}clear(){this.entries.clear()}}